/**
 * DOM manipulation utilities for WebView
 */

import { WebViewSize, WebViewPosition } from '../types'

export class DOMUtils {
  /**
   * Create iframe element with specified attributes
   */
  static createIframe(options: {
    src: string
    transparent?: boolean
    zIndex?: number
    cssClasses?: string[]
    sandbox?: string
    enablePointerEvents?: boolean
  }): HTMLIFrameElement {
    const iframe = document.createElement('iframe')

    // Basic attributes
    iframe.src = options.src
    iframe.style.cssText = this.getIframeStyles({
      transparent: options.transparent,
      zIndex: options.zIndex,
      enablePointerEvents: options.enablePointerEvents
    })

    // Sandbox attributes for security
    if (options.sandbox) {
      iframe.sandbox.value = options.sandbox
    } else {
      // Default sandbox permissions
      iframe.sandbox.add('allow-scripts', 'allow-same-origin', 'allow-forms', 'allow-popups')
    }

    // CSS classes
    if (options.cssClasses?.length) {
      iframe.className = options.cssClasses.join(' ')
    }

    // Additional attributes
    iframe.setAttribute('frameborder', '0')
    iframe.setAttribute('allowfullscreen', 'true')
    iframe.setAttribute('webkitallowfullscreen', 'true')
    iframe.setAttribute('mozallowfullscreen', 'true')

    return iframe
  }

  /**
   * Create iframe element with srcdoc
   */
  static createIframeWithSrcDoc(options: {
    srcdoc: string
    transparent?: boolean
    zIndex?: number
    cssClasses?: string[]
    sandbox?: string
    enablePointerEvents?: boolean
  }): HTMLIFrameElement {
    const iframe = document.createElement('iframe')

    // Set srcdoc instead of src
    iframe.srcdoc = options.srcdoc

    // Apply styles
    iframe.style.cssText = this.getIframeStyles({
      transparent: options.transparent,
      zIndex: options.zIndex,
      enablePointerEvents: options.enablePointerEvents
    })

    // Sandbox attributes for security
    if (options.sandbox) {
      iframe.sandbox.value = options.sandbox
    } else {
      // Default sandbox permissions
      iframe.sandbox.add('allow-scripts', 'allow-same-origin', 'allow-forms', 'allow-popups')
    }

    // CSS classes
    if (options.cssClasses?.length) {
      iframe.className = options.cssClasses.join(' ')
    }

    // Additional attributes
    iframe.setAttribute('frameborder', '0')
    iframe.setAttribute('allowfullscreen', 'true')
    iframe.setAttribute('webkitallowfullscreen', 'true')
    iframe.setAttribute('mozallowfullscreen', 'true')

    return iframe
  }

  /**
   * Generate CSS styles for iframe
   */
  static getIframeStyles(options: {
    transparent?: boolean
    zIndex?: number
    enablePointerEvents?: boolean
    fullscreen?: boolean
  } = {}): string {
    const styles = [
      'position: fixed',
      'top: 0',
      'left: 0',
      'width: 100%',
      'height: 100%',
      'border: none',
      'outline: none',
      'margin: 0',
      'padding: 0'
    ]

    // Z-index
    styles.push(`z-index: ${options.zIndex || 9999}`)

    // Background
    if (options.transparent) {
      styles.push('background: transparent')
    } else {
      styles.push('background: white')
    }

    // Pointer events
    if (options.enablePointerEvents === false) {
      styles.push('pointer-events: none')
    } else {
      styles.push('pointer-events: auto')
    }

    return styles.join('; ')
  }

  /**
   * Position iframe at specific coordinates
   */
  static positionIframe(iframe: HTMLIFrameElement, position: WebViewPosition): void {
    iframe.style.left = `${position.x}px`
    iframe.style.top = `${position.y}px`
    iframe.style.width = `${position.width}px`
    iframe.style.height = `${position.height}px`
    iframe.style.position = 'fixed'
  }

  /**
   * Make iframe fullscreen
   */
  static makeFullscreen(iframe: HTMLIFrameElement): void {
    iframe.style.left = '0'
    iframe.style.top = '0'
    iframe.style.width = '100%'
    iframe.style.height = '100%'
    iframe.style.position = 'fixed'
  }

  /**
   * Resize iframe to specific dimensions
   */
  static resizeIframe(iframe: HTMLIFrameElement, size: WebViewSize): void {
    iframe.style.width = `${size.width}px`
    iframe.style.height = `${size.height}px`
  }

  /**
   * Hide iframe
   */
  static hideIframe(iframe: HTMLIFrameElement): void {
    // iframe.style.display = 'none'
    iframe.style.opacity = '0';
    iframe.style.pointerEvents = 'none'; // отключаем взаимодействие
  }

  /**
   * Show iframe
   */
  static showIframe(iframe: HTMLIFrameElement): void {
    // iframe.style.display = 'block'
    iframe.style.opacity = '1';
    iframe.style.pointerEvents = 'auto';
    iframe.style.transition = 'opacity 0.1s ease-in-out'; // плавное появление
  }

  /**
   * Remove iframe from DOM
   */
  static removeIframe(iframe: HTMLIFrameElement): void {
    if (iframe.parentNode) {
      iframe.parentNode.removeChild(iframe)
    }
  }

  /**
   * Check if element is in DOM
   */
  static isInDOM(element: HTMLElement): boolean {
    return document.contains(element)
  }

  /**
   * Get window dimensions
   */
  static getWindowSize(): WebViewSize {
    return {
      width: window.innerWidth,
      height: window.innerHeight
    }
  }

  /**
   * Get iframe content window safely
   */
  static getIframeWindow(iframe: HTMLIFrameElement): Window | null {
    try {
      return iframe.contentWindow
    } catch (error) {
      console.warn('Cannot access iframe contentWindow:', error)
      return null
    }
  }

  /**
   * Get iframe content document safely
   */
  static getIframeDocument(iframe: HTMLIFrameElement): Document | null {
    try {
      return iframe.contentDocument
    } catch (error) {
      console.warn('Cannot access iframe contentDocument:', error)
      return null
    }
  }

  /**
   * Wait for iframe to load
   */
  static waitForIframeLoad(iframe: HTMLIFrameElement, timeout = 10000): Promise<void> {
    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        cleanup()
        reject(new Error(`Iframe load timeout after ${timeout}ms`))
      }, timeout)

      const onLoad = () => {
        cleanup()
        resolve()
      }

      const onError = (error: Event) => {
        cleanup()
        reject(new Error(`Iframe load error: ${error}`))
      }

      const cleanup = () => {
        clearTimeout(timeoutId)
        iframe.removeEventListener('load', onLoad)
        iframe.removeEventListener('error', onError)
      }

      // Check if already loaded
      if (iframe.contentDocument?.readyState === 'complete') {
        cleanup()
        resolve()
        return
      }

      iframe.addEventListener('load', onLoad)
      iframe.addEventListener('error', onError)
    })
  }

  /**
   * Debounced window resize handler
   */
  static createResizeHandler(callback: (size: WebViewSize) => void, delay = 100): () => void {
    let timeoutId: number | null = null

    return () => {
      if (timeoutId) {
        clearTimeout(timeoutId)
      }

      timeoutId = window.setTimeout(() => {
        callback(this.getWindowSize())
        timeoutId = null
      }, delay)
    }
  }

  /**
   * Create overlay div for blocking interactions
   */
  static createOverlay(zIndex = 9998): HTMLDivElement {
    const overlay = document.createElement('div')
    overlay.style.cssText = [
      'position: fixed',
      'top: 0',
      'left: 0',
      'width: 100%',
      'height: 100%',
      'background: transparent',
      'pointer-events: none',
      `z-index: ${zIndex}`
    ].join('; ')

    return overlay
  }

  /**
   * Check if running in iframe
   */
  static isInIframe(): boolean {
    try {
      return window.self !== window.top
    } catch (error) {
      // Cross-origin iframe will throw here
      return true
    }
  }

  /**
   * Get safe window reference for postMessage
   */
  static getSafeWindowReference(iframe: HTMLIFrameElement): Window | null {
    try {
      const win = iframe.contentWindow
      if (win && typeof win.postMessage === 'function') {
        return win
      }
    } catch (error) {
      console.warn('Cannot get safe window reference:', error)
    }
    return null
  }

  /**
   * Create emergency exit button - invisible button in top-right corner
   * that occupies 5% of screen width and height for emergency webview closure
   */
  static createEmergencyExitButton(options: {
    zIndex: number
    onExit: () => void
    debugMode?: boolean
  }): HTMLDivElement {
    const button = document.createElement('div')

    // Style the emergency exit button - completely invisible
    const baseStyles = [
      'position: fixed',
      'top: 0',
      'right: 0',
      'width: 5vw',
      'height: 5vh',
      'cursor: pointer',
      `z-index: ${options.zIndex}`,
      'pointer-events: auto',
      'user-select: none'
    ]

    // Add debug visual indicator if in debug mode
    if (options.debugMode) {
      button.style.cssText = [
        ...baseStyles,
        'background: rgba(255, 0, 0, 0.1)',
        'opacity: 0.5',
        'border: 1px solid rgba(255, 0, 0, 0.3)'
      ].join('; ')
      button.title = 'Emergency Exit (Debug Mode)'
    } else {
      // Production mode - completely invisible, no background, no border, no opacity
      button.style.cssText = [
        ...baseStyles,
        'background: none',
        'border: none',
        'opacity: 1'
      ].join('; ')
    }

    // Add click handler for emergency exit
    button.addEventListener('click', (event) => {
      event.preventDefault()
      event.stopPropagation()

      if (options.debugMode) {
        console.log('[DOMUtils] Emergency exit button clicked')
      }

      options.onExit()
    })

    // Add touch support for mobile
    button.addEventListener('touchend', (event) => {
      event.preventDefault()
      event.stopPropagation()

      if (options.debugMode) {
        console.log('[DOMUtils] Emergency exit button touched')
      }

      options.onExit()
    })

    return button
  }

  /**
   * Remove emergency exit button from DOM
   */
  static removeEmergencyExitButton(button: HTMLDivElement): void {
    if (button && button.parentNode) {
      button.parentNode.removeChild(button)
    }
  }
}
