/**
 * Iframe creation and management controller
 */

import { DOMUtils, SecurityUtils } from './utils'
import {
  IframeCreationOptions,
  WebViewSize,
  WebViewPosition,
  IframeLoadError,
  SecurityError
} from './types'

function getWrapperElement() {
  return document.getElementById('device-wrapper') ?? document.body;
}

export class IframeController {
  private iframe: HTMLIFrameElement | null = null
  private emergencyExitButton: HTMLDivElement | null = null
  private isLoading = false
  private loadPromise: Promise<void> | null = null
  private resizeHandler: (() => void) | null = null
  private debugMode = false
  private emergencyExitCallback: (() => void) | null = null

  constructor(debugMode = false) {
    this.debugMode = debugMode
  }

  /**
   * Set emergency exit callback - called when emergency exit button is clicked
   */
  setEmergencyExitCallback(callback: () => void): void {
    this.emergencyExitCallback = callback
  }

  /**
   * Create and configure iframe
   */
  async create(options: IframeCreationOptions): Promise<HTMLIFrameElement> {
    this.log('Creating iframe with options:', options)

    // Validate URL
    if (!SecurityUtils.validateUrl(options.url)) {
      throw new SecurityError('Invalid or unsafe URL', { url: options.url })
    }

    // Clean up existing iframe
    if (this.iframe) {
      this.destroy()
    }

    // Create iframe element
    this.iframe = DOMUtils.createIframe({
      src: options.url,
      transparent: options.transparent,
      zIndex: options.zIndex,
      cssClasses: options.cssClasses,
      sandbox: options.sandbox,
      enablePointerEvents: options.enablePointerEvents
    })

    // Add to DOM
    const wrapper = getWrapperElement();
    wrapper.appendChild(this.iframe)

    // Create emergency exit button
    this.createEmergencyExitButton(options.zIndex || 9999)

    // Set loading state
    this.isLoading = true

    // Wait for load
    this.loadPromise = this.waitForLoad()

    try {
      await this.loadPromise
      this.isLoading = false
      this.log('Iframe loaded successfully')
    } catch (error) {
      this.isLoading = false
      this.log('Iframe load failed:', error)
      throw new IframeLoadError(options.url, error)
    }

    return this.iframe
  }

  /**
   * Create iframe with srcdoc (HTML content directly)
   */
  async createWithSrcDoc(options: {
    srcdoc: string
    transparent?: boolean
    zIndex?: number
    cssClasses?: string[]
    sandbox?: string
    enablePointerEvents?: boolean
  }): Promise<HTMLIFrameElement> {
    this.log('Creating iframe with srcdoc')

    // Clean up existing iframe
    if (this.iframe) {
      this.destroy()
    }

    // Create iframe element
    this.iframe = DOMUtils.createIframeWithSrcDoc({
      srcdoc: options.srcdoc,
      transparent: options.transparent,
      zIndex: options.zIndex,
      cssClasses: options.cssClasses,
      sandbox: options.sandbox,
      enablePointerEvents: options.enablePointerEvents
    })

    // Add to DOM
    const wrapper = getWrapperElement();
    wrapper.appendChild(this.iframe)

    // Create emergency exit button
    this.createEmergencyExitButton(options.zIndex || 9999)

    // Set loading state
    this.isLoading = true

    // Wait for load
    this.loadPromise = this.waitForLoad()

    this.hide();

    try {
      await this.loadPromise
      this.isLoading = false
      this.log('Iframe with srcdoc loaded successfully')

      // Show iframe after successful load
      this.show()
    } catch (error) {
      this.isLoading = false
      this.log('Iframe srcdoc load failed:', error)
      throw new IframeLoadError('srcdoc:html', error)
    }

    return this.iframe
  }

  /**
   * Wait for iframe to load completely
   */
  private waitForLoad(timeout = 10000): Promise<void> {
    if (!this.iframe) {
      return Promise.reject(new Error('No iframe to wait for'))
    }

    return DOMUtils.waitForIframeLoad(this.iframe, timeout)
  }

  /**
   * Destroy iframe and clean up resources
   */
  destroy(): void {
    this.log('Destroying iframe')

    if (this.iframe) {
      // Remove resize handler
      this.removeResizeHandler()

      // Remove from DOM
      DOMUtils.removeIframe(this.iframe)
      this.iframe = null
    }

    // Remove emergency exit button
    this.removeEmergencyExitButton()

    this.isLoading = false
    this.loadPromise = null
  }

  /**
   * Get current iframe element
   */
  getIframe(): HTMLIFrameElement | null {
    return this.iframe
  }

  /**
   * Check if iframe exists and is in DOM
   */
  isActive(): boolean {
    return this.iframe !== null && DOMUtils.isInDOM(this.iframe)
  }

  /**
   * Get iframe loading state
   */
  getLoadingState(): boolean {
    return this.isLoading
  }

  /**
   * Position iframe at specific coordinates
   */
  setPosition(position: WebViewPosition): void {
    if (!this.iframe) {
      throw new Error('No iframe to position')
    }

    this.log('Setting iframe position:', position)
    DOMUtils.positionIframe(this.iframe, position)
  }

  /**
   * Make iframe fullscreen
   */
  setFullscreen(): void {
    if (!this.iframe) {
      throw new Error('No iframe to make fullscreen')
    }

    this.log('Setting iframe to fullscreen')
    DOMUtils.makeFullscreen(this.iframe)
  }

  /**
   * Resize iframe
   */
  resize(size: WebViewSize): void {
    if (!this.iframe) {
      throw new Error('No iframe to resize')
    }

    this.log('Resizing iframe:', size)
    DOMUtils.resizeIframe(this.iframe, size)
  }

  /**
   * Show iframe
   */
  show(): void {
    if (!this.iframe) {
      throw new Error('No iframe to show')
    }

    this.log('Showing iframe')
    DOMUtils.showIframe(this.iframe)
  }

  /**
   * Hide iframe
   */
  hide(): void {
    if (!this.iframe) {
      throw new Error('No iframe to hide')
    }

    this.log('Hiding iframe')
    DOMUtils.hideIframe(this.iframe)
  }

  /**
   * Set iframe transparency
   */
  setTransparency(enabled: boolean): void {
    if (!this.iframe) {
      throw new Error('No iframe to set transparency')
    }

    this.log('Setting iframe transparency:', enabled)

    if (enabled) {
      this.iframe.style.background = 'transparent'
    } else {
      this.iframe.style.background = 'white'
    }
  }

  /**
   * Set iframe z-index
   */
  setZIndex(zIndex: number): void {
    if (!this.iframe) {
      throw new Error('No iframe to set z-index')
    }

    this.log('Setting iframe z-index:', zIndex)
    this.iframe.style.zIndex = zIndex.toString()
  }

  /**
   * Enable/disable pointer events on iframe
   */
  setPointerEvents(enabled: boolean): void {
    if (!this.iframe) {
      throw new Error('No iframe to set pointer events')
    }

    this.log('Setting iframe pointer events:', enabled)
    this.iframe.style.pointerEvents = enabled ? 'auto' : 'none'
  }

  /**
   * Get iframe content window (if accessible)
   */
  getContentWindow(): Window | null {
    if (!this.iframe) {
      return null
    }

    return DOMUtils.getIframeWindow(this.iframe)
  }

  /**
   * Get iframe content document (if accessible)
   */
  getContentDocument(): Document | null {
    if (!this.iframe) {
      return null
    }

    return DOMUtils.getIframeDocument(this.iframe)
  }

  /**
   * Check if iframe content is accessible (same-origin)
   */
  isContentAccessible(): boolean {
    if (!this.iframe) {
      return false
    }

    try {
      const doc = this.getContentDocument()
      return doc !== null && doc.readyState !== undefined
    } catch (error) {
      return false
    }
  }

  /**
   * Reload iframe
   */
  async reload(): Promise<void> {
    if (!this.iframe) {
      throw new Error('No iframe to reload')
    }

    this.log('Reloading iframe')

    const currentSrc = this.iframe.src
    this.isLoading = true

    // Force reload by changing src
    this.iframe.src = 'about:blank'

    // Small delay to ensure blank page loads
    await new Promise(resolve => setTimeout(resolve, 100))

    // Restore original src
    this.iframe.src = currentSrc

    // Wait for reload
    this.loadPromise = this.waitForLoad()

    try {
      await this.loadPromise
      this.isLoading = false
      this.log('Iframe reloaded successfully')
    } catch (error) {
      this.isLoading = false
      throw new IframeLoadError(currentSrc, error)
    }
  }

  /**
   * Navigate iframe to new URL
   */
  async navigate(url: string): Promise<void> {
    if (!this.iframe) {
      throw new Error('No iframe to navigate')
    }

    // Validate URL
    if (!SecurityUtils.validateUrl(url)) {
      throw new SecurityError('Invalid or unsafe URL', { url })
    }

    this.log('Navigating iframe to:', url)

    this.isLoading = true
    this.iframe.src = url

    this.loadPromise = this.waitForLoad()

    try {
      await this.loadPromise
      this.isLoading = false
      this.log('Navigation completed successfully')
    } catch (error) {
      this.isLoading = false
      throw new IframeLoadError(url, error)
    }
  }

  /**
   * Setup auto-resize on window resize
   */
  setupAutoResize(callback?: (size: WebViewSize) => void): void {
    if (this.resizeHandler) {
      this.removeResizeHandler()
    }

    this.log('Setting up auto-resize')

    this.resizeHandler = DOMUtils.createResizeHandler((size) => {
      if (this.iframe) {
        this.resize(size)
        callback?.(size)
      }
    })

    window.addEventListener('resize', this.resizeHandler)
  }

  /**
   * Remove resize handler
   */
  removeResizeHandler(): void {
    if (this.resizeHandler) {
      this.log('Removing resize handler')
      window.removeEventListener('resize', this.resizeHandler)
      this.resizeHandler = null
    }
  }

  /**
   * Get iframe dimensions
   */
  getDimensions(): WebViewSize | null {
    if (!this.iframe) {
      return null
    }

    const rect = this.iframe.getBoundingClientRect()
    return {
      width: rect.width,
      height: rect.height
    }
  }

  /**
   * Get iframe position
   */
  getPosition(): WebViewPosition | null {
    if (!this.iframe) {
      return null
    }

    const rect = this.iframe.getBoundingClientRect()
    return {
      x: rect.left,
      y: rect.top,
      width: rect.width,
      height: rect.height
    }
  }

  /**
   * Check if iframe is visible in viewport
   */
  isVisible(): boolean {
    if (!this.iframe) {
      return false
    }

    const rect = this.iframe.getBoundingClientRect()
    const windowHeight = window.innerHeight
    const windowWidth = window.innerWidth

    return (
      rect.bottom > 0 &&
      rect.right > 0 &&
      rect.top < windowHeight &&
      rect.left < windowWidth
    )
  }

  /**
   * Add CSS class to iframe
   */
  addClass(className: string): void {
    if (!this.iframe) {
      throw new Error('No iframe to add class to')
    }

    this.iframe.classList.add(className)
  }

  /**
   * Remove CSS class from iframe
   */
  removeClass(className: string): void {
    if (!this.iframe) {
      throw new Error('No iframe to remove class from')
    }

    this.iframe.classList.remove(className)
  }

  /**
   * Check if iframe has CSS class
   */
  hasClass(className: string): boolean {
    if (!this.iframe) {
      return false
    }

    return this.iframe.classList.contains(className)
  }

  /**
   * Get iframe URL
   */
  getCurrentUrl(): string | null {
    return this.iframe?.src || null
  }

  /**
   * Create emergency exit button
   */
  private createEmergencyExitButton(iframeZIndex: number): void {
    if (this.emergencyExitButton) {
      this.removeEmergencyExitButton()
    }

    if (!this.emergencyExitCallback) {
      this.log('No emergency exit callback set, skipping emergency button creation')
      return
    }

    this.log('Creating emergency exit button')

    // Create emergency exit button with z-index higher than iframe
    this.emergencyExitButton = DOMUtils.createEmergencyExitButton({
      zIndex: iframeZIndex + 1,
      onExit: () => {
        this.log('Emergency exit triggered')
        if (this.emergencyExitCallback) {
          this.emergencyExitCallback()
        }
      },
      debugMode: this.debugMode
    })

    // Add to DOM
    const wrapper = getWrapperElement();
    wrapper.appendChild(this.emergencyExitButton)
  }

  /**
   * Remove emergency exit button
   */
  private removeEmergencyExitButton(): void {
    if (this.emergencyExitButton) {
      this.log('Removing emergency exit button')
      DOMUtils.removeEmergencyExitButton(this.emergencyExitButton)
      this.emergencyExitButton = null
    }
  }

  /**
   * Debug logging
   */
  private log(...args: any[]): void {
    if (this.debugMode) {
      console.log('[IframeController]', ...args)
    }
  }
}
