/**
 * Code injection utilities for WebView
 */

import { SecurityUtils, DOMUtils } from './utils'
import {
  CodeInjectionResult,
  CodeInjectionError,
  SecurityError,
  MessageTypes
} from './types'

export class CodeInjector {
  private iframe: HTMLIFrameElement | null = null
  private debugMode = false
  private injectedScripts = new Set<string>()

  constructor(debugMode = false) {
    this.debugMode = debugMode
  }

  /**
   * Initialize injector with iframe reference
   */
  initialize(iframe: HTMLIFrameElement): void {
    this.iframe = iframe
    this.log('CodeInjector initialized with iframe')
  }

  /**
   * Inject JavaScript code into iframe
   */
  async injectCode(code: string, options: {
    sanitize?: boolean
    allowEval?: boolean
    allowFunction?: boolean
    timeout?: number
  } = {}): Promise<CodeInjectionResult> {
    const startTime = Date.now()

    try {
      if (!this.iframe) {
        throw new CodeInjectionError('No iframe available for code injection')
      }

      // Sanitize code if requested
      let finalCode = code
      if (options.sanitize !== false) {
        finalCode = SecurityUtils.sanitizeCode(code, {
          allowEval: options.allowEval,
          allowFunction: options.allowFunction
        })

        if (finalCode !== code) {
          this.log('Code was sanitized during injection')
        }
      }

      this.log('Injecting code:', finalCode.substring(0, 100) + '...')

      // Try different injection methods based on accessibility
      const result = await this.attemptInjection(finalCode, options.timeout)

      const executionTime = Date.now() - startTime
      this.log('Code injection completed in', executionTime, 'ms')

      return {
        success: true,
        executionTime
      }

    } catch (error) {
      const executionTime = Date.now() - startTime
      console.log('??? Code injection failed:', error)

      return {
        success: false,
        error: error instanceof Error ? error.message : String(error),
        executionTime
      }
    }
  }

  /**
   * Inject external script by URL
   */
  async injectScript(scriptUrl: string, options: {
    timeout?: number
    cache?: boolean
  } = {}): Promise<CodeInjectionResult> {
    const startTime = Date.now()

    try {
      if (!this.iframe) {
        throw new CodeInjectionError('No iframe available for script injection')
      }

      // Validate script URL
      if (!SecurityUtils.validateUrl(scriptUrl)) {
        throw new SecurityError('Invalid or unsafe script URL', { url: scriptUrl })
      }

      // Check if already injected (if caching enabled)
      if (options.cache !== false && this.injectedScripts.has(scriptUrl)) {
        this.log('Script already injected (cached):', scriptUrl)
        return {
          success: true,
          executionTime: Date.now() - startTime
        }
      }

      this.log('Injecting script:', scriptUrl)

      // Create script loading code
      const scriptCode = this.createScriptLoader(scriptUrl, options.timeout)

      // Inject the script loader
      const result = await this.injectCode(scriptCode, { sanitize: false })

      if (result.success && options.cache !== false) {
        this.injectedScripts.add(scriptUrl)
      }

      return result

    } catch (error) {
      const executionTime = Date.now() - startTime

      return {
        success: false,
        error: error instanceof Error ? error.message : String(error),
        executionTime
      }
    }
  }

  /**
   * Wait for iframe to be ready for injection
   */
  async waitForReady(timeout = 5000): Promise<void> {
    if (!this.iframe) {
      throw new CodeInjectionError('No iframe to wait for')
    }

    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        reject(new CodeInjectionError(`Iframe ready timeout after ${timeout}ms`))
      }, timeout)

      const checkReady = () => {
        if (this.isIframeReady()) {
          clearTimeout(timeoutId)
          resolve()
        } else {
          setTimeout(checkReady, 100)
        }
      }

      checkReady()
    })
  }

  /**
   * Create bootstrap script for cross-origin communication
   */
  createBootstrap(): string {
    return `
      (function() {
        // Balancy WebView Bootstrap
        window.balancyWebView = {
          version: '1.0.0',
          ready: false,
          
          // Message handling
          sendMessage: function(message) {
            if (window.parent && window.parent.postMessage) {
              window.parent.postMessage({
                type: '${MessageTypes.USER_DATA}',
                payload: message,
                timestamp: Date.now(),
                id: 'bootstrap_' + Math.random().toString(36).substr(2, 9)
              }, '*');
            }
          },
          
          // Code execution
          executeCode: function(code) {
            try {
              const result = eval(code);
              this.sendMessage({
                type: 'code-execution-result',
                success: true,
                result: result
              });
            } catch (error) {
              this.sendMessage({
                type: 'code-execution-result',
                success: false,
                error: error.message
              });
            }
          },
          
          // Ready notification
          notifyReady: function() {
            this.ready = true;
            this.sendMessage({
              type: 'bootstrap-ready',
              version: this.version
            });
          }
        };
        
        // Listen for parent messages
        window.addEventListener('message', function(event) {
          if (event.data && event.data.type === '${MessageTypes.CODE_INJECT}') {
            window.balancyWebView.executeCode(event.data.payload.code);
          }
        });
        
        // Notify parent that bootstrap is ready
        if (document.readyState === 'complete') {
          window.balancyWebView.notifyReady();
        } else {
          window.addEventListener('load', function() {
            window.balancyWebView.notifyReady();
          });
        }
      })();
    `
  }

  /**
   * Inject bootstrap script for cross-origin communication
   */
  async injectBootstrap(): Promise<CodeInjectionResult> {
    const bootstrap = this.createBootstrap()
    return this.injectCode(bootstrap, { sanitize: false })
  }

  /**
   * Destroy injector and clean up
   */
  destroy(): void {
    this.log('Destroying CodeInjector')
    this.iframe = null
    this.injectedScripts.clear()
  }

  /**
   * Get list of injected scripts
   */
  getInjectedScripts(): string[] {
    return Array.from(this.injectedScripts)
  }

  /**
   * Clear injected scripts cache
   */
  clearScriptsCache(): void {
    this.injectedScripts.clear()
    this.log('Scripts cache cleared')
  }

  /**
   * Attempt code injection using available methods
   */
  private async attemptInjection(code: string, timeout = 5000): Promise<void> {
    if (!this.iframe) {
      throw new CodeInjectionError('No iframe available')
    }

    // Method 1: Direct execution (same-origin)
    if (this.canDirectExecute()) {
      this.log('Using direct execution method')
      return this.directExecute(code)
    }

    // Method 2: PostMessage injection (cross-origin)
    this.log('Using postMessage injection method')
    return this.postMessageExecute(code, timeout)
  }

  /**
   * Check if direct execution is possible (same-origin)
   */
  private canDirectExecute(): boolean {
    if (!this.iframe) return false

    try {
      const doc = DOMUtils.getIframeDocument(this.iframe)
      return doc !== null && doc.readyState !== undefined
    } catch (error) {
      return false
    }
  }

  /**
   * Execute code directly in iframe (same-origin only)
   */
  private async directExecute(code: string): Promise<void> {
    if (!this.iframe) {
      throw new CodeInjectionError('No iframe available')
    }

    const contentWindow = DOMUtils.getIframeWindow(this.iframe)
    if (!contentWindow) {
      throw new CodeInjectionError('Cannot access iframe content window')
    }

    try {
      // Execute code in iframe context
      const func = new (contentWindow as any).Function(code)
      await func()
    } catch (error) {
      throw new CodeInjectionError('Direct execution failed', { error })
    }
  }

  /**
   * Execute code via postMessage (cross-origin)
   */
  private async postMessageExecute(code: string, timeout: number): Promise<void> {
    if (!this.iframe) {
      throw new CodeInjectionError('No iframe available')
    }

    return new Promise((resolve, reject) => {
      const messageId = SecurityUtils.generateMessageId()

      // Setup timeout
      const timeoutId = setTimeout(() => {
        cleanup()
        reject(new CodeInjectionError(`Code injection timeout after ${timeout}ms`))
      }, timeout)

      // Setup response listener
      const responseHandler = (event: MessageEvent) => {
        if (event.data?.type === 'code-execution-result' && event.data?.messageId === messageId) {
          cleanup()

          if (event.data.success) {
            resolve()
          } else {
            reject(new CodeInjectionError('Code execution failed', { error: event.data.error }))
          }
        }
      }

      const cleanup = () => {
        clearTimeout(timeoutId)
        window.removeEventListener('message', responseHandler)
      }

      window.addEventListener('message', responseHandler)

      // Send code injection message
      const contentWindow = DOMUtils.getSafeWindowReference(this.iframe!)
      if (!contentWindow) {
        cleanup()
        reject(new CodeInjectionError('Cannot get iframe window reference'))
        return
      }

      try {
        contentWindow.postMessage({
          type: MessageTypes.CODE_INJECT,
          payload: { code },
          id: messageId,
          timestamp: Date.now()
        }, '*')
      } catch (error) {
        cleanup()
        reject(new CodeInjectionError('Failed to send injection message', { error }))
      }
    })
  }

  /**
   * Create script loader code
   */
  private createScriptLoader(url: string, timeout = 10000): string {
    return `
      (function() {
        return new Promise(function(resolve, reject) {
          var script = document.createElement('script');
          var timeoutId = setTimeout(function() {
            cleanup();
            reject(new Error('Script load timeout: ${url}'));
          }, ${timeout});
          
          function cleanup() {
            clearTimeout(timeoutId);
            script.removeEventListener('load', onLoad);
            script.removeEventListener('error', onError);
          }
          
          function onLoad() {
            cleanup();
            resolve();
          }
          
          function onError(error) {
            cleanup();
            reject(new Error('Script load error: ${url}'));
          }
          
          script.addEventListener('load', onLoad);
          script.addEventListener('error', onError);
          script.src = '${url}';
          script.type = 'text/javascript';
          
          var head = document.head || document.getElementsByTagName('head')[0];
          head.appendChild(script);
        });
      })();
    `
  }

  /**
   * Check if iframe is ready for injection
   */
  private isIframeReady(): boolean {
    if (!this.iframe) return false

    try {
      // For same-origin, check document state
      if (this.canDirectExecute()) {
        const doc = DOMUtils.getIframeDocument(this.iframe)
        return doc?.readyState === 'complete'
      }

      // For cross-origin, assume ready if window is accessible
      const win = DOMUtils.getSafeWindowReference(this.iframe)
      return win !== null

    } catch (error) {
      return false
    }
  }

  /**
   * Debug logging
   */
  private log(...args: any[]): void {
    if (this.debugMode) {
      console.log('[CodeInjector]', ...args)
    }
  }
}
